import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as i}from"./chunks/EN.P9aPnFBv.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as a,o as s,c as n,a3 as r}from"./chunks/framework.g9mfNVRQ.js";const y=JSON.parse('{"title":"G6, ONE","description":"","frontmatter":{},"headers":[],"relativePath":"install/g6.md","filePath":"install/g6.md"}'),l={name:"install/g6.md"};function c(d,o,m,p,h,u){return s(),n("div",null,[...o[0]||(o[0]=[r('<div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  Hardware Data Source<br>   Dex</p></div><h3 id="g6-or-dexcom-one" tabindex="-1">G6 or Dexcom ONE <a class="header-anchor" href="#g6-or-dexcom-one" aria-label="Permalink to &quot;G6 or Dexcom ONE&quot;">​</a></h3><p>This describes how to set up a Dexcom G6 or Dexcom ONE transmitter and sensor with xDrip. From xDrip&#39;s perspective the two are the same device — same transmitter hardware, same BLE protocol — so every step below applies equally to both.</p><p>Reference documentation is <a href="https://navid200.github.io/xDrip/docs/Dexcom_page.html" target="_blank" rel="noreferrer">here</a>.</p><p>For G7 or ONE+, see the <a href="./g7.html">separate G7, ONE+ page</a> instead.</p><h4 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h4><ul><li>Check your phone setup matches xDrip <a href="./prerequisites.html">prerequisites</a>.</li><li>You cannot normally have both xDrip and the Dexcom app collecting directly from the same transmitter at the same time. Uninstall the Dexcom app if you want xDrip to be the collector. If you need to keep using the Dexcom app, only it can be the collector — set up xDrip as a <a href="./companion.html">Companion app</a> follower instead.</li></ul><div class="warning custom-block"><p class="custom-block-title">Don&#39;t pair from Android Bluetooth settings</p><p>Never try to pair the transmitter from the Android Bluetooth settings page — let xDrip trigger the pairing request instead, and approve it when asked. The transmitter only transmits for a few seconds once every 5 minutes, so don&#39;t be surprised if Android doesn&#39;t list it under paired devices most of the time.</p></div><p>The <a href="./../troubleshoot/systemstatus.html">System Status</a> page (top-left menu) has a &quot;Dex Status&quot; heading with the parameters you&#39;ll need throughout this page: transmitter ID, time since last connection, firmware version, transmitter days, and battery voltages.</p><h4 id="dexcom-device-compatibility" tabindex="-1">Dexcom device compatibility <a class="header-anchor" href="#dexcom-device-compatibility" aria-label="Permalink to &quot;Dexcom device compatibility&quot;">​</a></h4><ul><li><strong>t:slim pump</strong> — start the G6 sensor <strong>on the pump</strong>, not in xDrip, and don&#39;t also start it in xDrip. After the warm-up period xDrip will detect and pick up the running session on its own (tap <strong>Restart Collector</strong> on the Classic Status page if it doesn&#39;t). You don&#39;t need to enter the calibration code into xDrip either — only the transmitter needs it.</li><li><strong>Dexcom receiver</strong> — you can run it alongside xDrip, but avoid sending duplicate start/stop/calibrate commands from both. If you must use the receiver, start the sensor there and let xDrip pick up the session after warm-up. Don&#39;t stop the sensor from xDrip thinking it only affects xDrip — it stops the whole session on the transmitter.</li><li>You <strong>cannot</strong> use a t:slim pump and a Dexcom receiver at the same time (they need the same transmitter slot), and you cannot use xDrip and the Dexcom app at the same time either — unless the Dexcom app is the only one collecting, in which case xDrip can follow it via the <a href="./companion.html">Companion app</a>.</li></ul><h4 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h4><p>To start, you need a transmitter and a sensor.</p><div class="info custom-block"><p class="custom-block-title">Transmitter expiry</p><p>Check the two dates printed on the transmitter box: the manufacture date, and a Ship-By or Use-By date. Don&#39;t accept a transmitter whose Ship-By/Use-By date has already passed. Don&#39;t remove a transmitter from its box, or touch its contacts, until you intend to use it — an internal day counter starts the moment you do, and it cannot be stopped. The <a href="./../troubleshoot/g6.html#transmitter-warranty">warranty</a> is only valid if you start using the transmitter within 5 months of it being shipped to you, and the last day you can start (or restart) a sensor on a G6 transmitter is transmitter day 99.</p></div><h4 id="setup-xdrip" tabindex="-1">Set up xDrip <a class="header-anchor" href="#setup-xdrip" aria-label="Permalink to &quot;Set up xDrip {#setup-xdrip}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  Hardware Data Source<br>   Dex</p></div><p>Then verify the settings below — most match xDrip defaults, so this is a check rather than a reconfiguration. What each setting does is described in the <a href="#dexcom-advanced-settings-reference">Dexcom advanced settings reference</a>, <a href="./../use/bluetooth.html">Bluetooth Settings</a> and <a href="./../use/misc.html">Other misc. options</a> pages.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  Dex Debug Settings</p></div><div class="admonition xdripitem"><p class="admonition-title">Native Algorithm <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Use the transmitter&#39;s internal algorithm to calculate glucose values when possible.</p></div><div class="admonition xdripitem"><p class="admonition-title">Restart Sensor <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Automatically restart a sensor when it stops</p></div><div class="admonition xdripitem"><p class="admonition-title">Preemptive restarts <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Preemptively restart a sensor before the session ends on day 6/9 to avoid the warm-up time</p></div><p>Keep both restart options disabled. Reusing the same sensor beyond its normal session is a separate, riskier technique — read <a href="./../troubleshoot/g6.html#restarting-a-sensor-beyond-its-normal-session">Restarting a sensor</a> before considering it.</p><div class="admonition xdripitem"><p class="admonition-title">Go on without calibrations <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Keep using data even if there are not enough good calibrations (Experimental!)</p></div><div class="admonition xdripitem"><p class="admonition-title">Minimize Scanning <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Use heuristics to minimize Bluetooth scanning + save power</p></div><div class="admonition xdripitem"><p class="admonition-title">Avoid Scanning <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Avoid scanning as much as possible (reduces battery usage further)</p></div><div class="info custom-block"><p class="custom-block-title">Scanning options</p><p>Minimize Scanning and Avoid Scanning save battery but are disastrous on some phones (Samsung, Chinese brands, ...). Start with both disabled — only try enabling them, one at a time, once your connection is reliable.</p></div><div class="admonition xdripitem"><p class="admonition-title">Allow OB1 unbonding <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> OB1 collector can unbond if it thinks the encryption has failed. If you get problems with it unpairing then disable this option. If you then totally lose connection, make sure this is enabled.</p></div><div class="admonition xdripitem"><p class="admonition-title">Special Pairing Workaround <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Some Samsung devices can have an error where they lose the pairing information. This attempts to work around the issue.</p></div><p>Enable Special Pairing Workaround on Samsung and some Chinese phones.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  <a href="./../use/lesscommon.html">Less common settings</a><br>   <a href="./../use/misc.html">Other misc. options</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Engineering mode <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Allows changing the most unsafe settings which could break everything!</p></div><div class="admonition xdripitem"><p class="admonition-title">Battery Optimization prompt <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> On Android 6+ ensure battery optimization is switched off (recommended)</p></div><div class="admonition xdripitem"><p class="admonition-title">Wake Workarounds <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Use workarounds to avoid non-standard Android behavior of some handsets. Without this, collectors usually fail to get data.</p></div><div class="admonition xdripitem"><p class="admonition-title">Use Excessive Wakelocks <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Older gratuitous wakelocks which can drain extra battery but might be needed for Nightwatch or Android Wear.</p></div><div class="admonition xdripitem"><p class="admonition-title">Display Predictive Values <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Old method - Not recommended!</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  <a href="./../use/lesscommon.html">Less common settings</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Aggressive service restarts <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Repeatedly restart the collection service at any hint of missing data. Enable only if you are getting data loss.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  <a href="./../use/lesscommon.html">Less common settings</a><br>   <a href="./../calibrate/advancedcal.html">Advanced Calibration</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Automatic Calibration <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Calibrate using new blood glucose readings if the conditions appear right to do so without asking confirmation (experimental)</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  <a href="./../use/lesscommon.html">Less common settings</a><br>   <a href="./../use/bluetooth.html">Bluetooth Settings</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Turn Bluetooth on <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Automatically enable Bluetooth if it is switched off when we try to connect to a Bluetooth device</p></div><div class="admonition xdripitem"><p class="admonition-title">Bluetooth Watchdog <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Reset Bluetooth by turning it off and on if we don&#39;t get anything in 20 minutes</p></div><div class="admonition xdripitem"><p class="admonition-title">Close GATT on BLE disconnect <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> If the Bluetooth watchdog activates often then you can try unchecking this option to see if it helps</p></div><div class="admonition xdripitem"><p class="admonition-title">Use scanning <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Scan before connecting on xBridge and Libre Bluetooth</p></div><div class="admonition xdripitem"><p class="admonition-title">Use BLE manager <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Use a more modern BLE manager system</p></div><div class="admonition xdripitem"><p class="admonition-title">Trust Auto-Connect <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Use and trust Android Bluetooth auto connect feature</p></div><p>Start with Trust Auto-Connect disabled. Try enabling it only if you keep losing the connection.</p><div class="admonition xdripitem"><p class="admonition-title">Use Background Scans <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Use Android 8+ background scanning feature</p></div><div class="admonition xdripitem"><p class="admonition-title">Companion Bluetooth <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Use Bluetooth with companion app data source</p></div><div class="admonition xdripitem"><p class="admonition-title">Bluetooth Wakelocks <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Older Bluetooth wakelocks which can drain extra battery but might be needed for Bluetooth reception</p></div><div class="admonition xdripitem"><p class="admonition-title">xBridge+ Polling Mode <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Experimental support for xBridge+ polling feature</p></div><h4 id="setting-up-for-the-first-time" tabindex="-1">Setting up for the first time <a class="header-anchor" href="#setting-up-for-the-first-time" aria-label="Permalink to &quot;Setting up for the first time&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">Please be patient</p><p>Do not rush to tap &quot;Start Sensor&quot; even if xDrip encourages you to. Follow the steps below in order to avoid the most common issues.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  Hardware Data Source<br>   Dex</p></div><ol><li>If you&#39;re using a brand-new transmitter, take note of its serial number, printed on the transmitter and on its box. It activates as soon as you snap it into a sensor — you&#39;ll need this number for up to 110 days. If the serial number ends in <code>-1</code>, use only the first six characters.</li><li>Every sensor has a 4-digit calibration code printed on its adhesive cover — you&#39;ll need it to start the session. Don&#39;t open the sensor container until you&#39;re ready to insert it, and don&#39;t throw away the adhesive cover before you&#39;ve noted the code.</li><li>If there&#39;s a command stuck in the queue on the Dex Status page, <a href="./../troubleshoot/g6.html#transmitter-queue-stuck">clear the queue</a> before continuing.</li><li>If &quot;Start Sensor&quot; isn&#39;t offered as an option from the top-left menu, tap &quot;Stop Sensor&quot; instead and wait 5 minutes.</li><li>The transmitter must be detached from your body for at least 10 minutes before you proceed — <a href="./../troubleshoot/g6.html#removing-a-transmitter-without-damaging-the-sensor">removing it without damaging the sensor</a> explains how, if you&#39;re moving it from a previous sensor.</li><li>If you&#39;re activating a new transmitter, enter its serial number as the <a href="#dexcom-transmitter-id">Dexcom Transmitter ID</a>.</li><li>Clean the transmitter contacts with rubbing alcohol (skip this if you&#39;re restarting the same sensor) and let them dry for about 10 seconds. Snap the transmitter into the sensor — this is what activates a brand-new transmitter.</li><li>Insert the sensor following the manufacturer&#39;s applicator instructions. Keep dust and blood away from the contacts.</li><li>Watch the <a href="./../troubleshoot/systemstatus.html">System Status</a> Dex Status page — it updates every 5 minutes. Don&#39;t proceed if you don&#39;t have proper connectivity; sort that out first. If you&#39;re activating a new transmitter, be patient and wait for the battery voltages to appear before continuing — it can take up to half an hour.</li><li>Tap Start Sensor and enter the 4-digit calibration code from the sensor&#39;s adhesive cover when asked. Keep the code — you may need it again later.</li></ol><div class="warning custom-block"><p class="custom-block-title">Never soak a sensor</p><p>Never soak (insert a sensor a while before starting it in xDrip). Factory calibration is the main advantage of G6/ONE over G5, and soaking interferes with it. The longer the gap between inserting the sensor and starting it, the more you undermine that accuracy.</p></div><p>Readings normally start about 2 hours after starting the sensor, with no initial calibration needed. If you&#39;re coming from G5 or another CGM, give factory calibration a chance — most people don&#39;t need to calibrate a G6/ONE sensor at all as long as the calibration code was entered correctly.</p><h4 id="starting-a-subsequent-sensor" tabindex="-1">Starting a subsequent sensor <a class="header-anchor" href="#starting-a-subsequent-sensor" aria-label="Permalink to &quot;Starting a subsequent sensor&quot;">​</a></h4><p>When one sensor&#39;s session ends, a single transmitter can be moved on to a new sensor and reused — up to around 11 sensors over its lifetime.</p><ol><li>Tap Stop Sensor from the top-left menu (even if the sensor has already stopped and &quot;Start Sensor&quot; isn&#39;t offered yet). Wait for &quot;stop sensor&quot; to clear the queue on the Dex Status page — this normally takes about 5 minutes.</li><li><a href="./../troubleshoot/g6.html#removing-a-transmitter-without-damaging-the-sensor">Remove the old transmitter without damaging the sensor</a> it&#39;s currently in, so you can keep using the sensor&#39;s adhesive site, or simply peel off the old sensor if you&#39;re done with it.</li><li>Follow <a href="#setting-up-for-the-first-time">Setting up for the first time</a> again from step 5 onward, using the new sensor&#39;s own calibration code.</li></ol><div class="info custom-block"><p class="custom-block-title">Info</p><p>Reusing the <em>same</em> sensor for longer than its normal session by tricking the transmitter into restarting it is a separate, riskier technique with a real risk of causing incorrect high readings — see <a href="./../troubleshoot/g6.html#restarting-a-sensor-beyond-its-normal-session">Restarting a sensor</a> in troubleshooting before attempting it.</p></div><h4 id="calibration" tabindex="-1">Calibration <a class="header-anchor" href="#calibration" aria-label="Permalink to &quot;Calibration&quot;">​</a></h4><p>See <a href="./../calibrate/101.html">Calibration basics</a> and <a href="./../calibrate/calibrate.html">Calibrate</a> for what calibration is and when you should do it. You shouldn&#39;t need to calibrate a G6/ONE sensor at all under normal factory calibration — over-calibrating is discouraged by the manufacturer too.</p><p>If you do need to calibrate, tap &quot;Add Calibration&quot; from the top-left menu. This only becomes available after at least 3 readings have come in following a sensor start or restart. Only calibrate when the trend is flat or close to flat, and never enter a calibration that corrects the current reading by more than 20%. If you need a bigger correction, space consecutive calibrations at least 25 minutes apart (45 minutes before a third one) rather than doing it in one large step — otherwise you risk a confused calibration error that can stop readings for hours with no way to know how long the recovery will take.</p><h4 id="problems" tabindex="-1">Problems? <a class="header-anchor" href="#problems" aria-label="Permalink to &quot;Problems?&quot;">​</a></h4><p>Try the <a href="./../troubleshoot/g6.html">G6, ONE troubleshooting</a> page.</p><br><hr><h3 id="dexcom-advanced-settings-reference" tabindex="-1">Dexcom advanced settings reference <a class="header-anchor" href="#dexcom-advanced-settings-reference" aria-label="Permalink to &quot;Dexcom advanced settings reference&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  Dexcom Transmitter ID<br>  Dex Debug Settings</p></div><p>Reference documentation is <a href="https://navid200.github.io/xDrip/docs/Dexcom_page.html" target="_blank" rel="noreferrer">here</a>.</p><br><h4 id="dexcom-transmitter-id" tabindex="-1">Dexcom Transmitter ID <a class="header-anchor" href="#dexcom-transmitter-id" aria-label="Permalink to &quot;Dexcom Transmitter ID&quot;">​</a></h4><p>Tells xDrip which transmitter to scan for, authenticate against, and associate incoming BLE traffic with.</p><p><em>Collector: Dexcom collectors and Dex-related bridge paths — Dexcom G5/G6/G7 and some Dex bridge setups</em></p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  Dexcom Transmitter ID</p></div><div class="admonition xdripitem"><p class="admonition-title">Dexcom Transmitter ID</p><p> ID of your Dexcom Transmitter, e.g. 12AB3</p></div><p>Enter the transmitter serial number (first six characters only if it ends in <code>-1</code>).</p><h4 id="native-algorithm" tabindex="-1">Native Algorithm <a class="header-anchor" href="#native-algorithm" aria-label="Permalink to &quot;Native Algorithm&quot;">​</a></h4><p>Uses the transmitter&#39;s own glucose/eGlucose request path when supported, instead of the raw sensor-data path.</p><p><em>Collector: OB1 Dex collector (<code>Ob1G5CollectionService</code>) — Dexcom G5/G6/G7</em></p><div class="admonition xdripitem"><p class="admonition-title">Native Algorithm</p></div><h4 id="minimize-scanning" tabindex="-1">Minimize Scanning <a class="header-anchor" href="#minimize-scanning" aria-label="Permalink to &quot;Minimize Scanning&quot;">​</a></h4><p>Reduces scan frequency using timing and known-device heuristics to save battery.</p><p><em>Collector: OB1 Dex collector (<code>Ob1G5CollectionService</code>) — Dexcom G5/G6/G7</em></p><div class="admonition xdripitem"><p class="admonition-title">Minimize Scanning</p></div><h4 id="avoid-scanning" tabindex="-1">Avoid Scanning <a class="header-anchor" href="#avoid-scanning" aria-label="Permalink to &quot;Avoid Scanning&quot;">​</a></h4><p>Pushes scan reduction further, relying more heavily on previously known transmitter timing and identity.</p><p><em>Collector: OB1 Dex collector (<code>Ob1G5CollectionService</code>) — Dexcom G5/G6/G7</em></p><div class="admonition xdripitem"><p class="admonition-title">Avoid Scanning</p></div><h4 id="allow-ob1-unbonding" tabindex="-1">Allow OB1 unbonding <a class="header-anchor" href="#allow-ob1-unbonding" aria-label="Permalink to &quot;Allow OB1 unbonding&quot;">​</a></h4><p>Allows xDrip to remove and rebuild the BLE bond when Dexcom pairing or encryption gets into a bad state.</p><p><em>Collector: OB1 Dex collector (<code>Ob1G5CollectionService</code>) — Dexcom G5/G6/G7</em></p><div class="admonition xdripitem"><p class="admonition-title">Allow OB1 unbonding</p></div><h4 id="special-pairing-workaround" tabindex="-1">Special pairing workaround <a class="header-anchor" href="#special-pairing-workaround" aria-label="Permalink to &quot;Special pairing workaround&quot;">​</a></h4><p>Changes the OB1 pairing/connection sequence to work around device-specific bonding problems.</p><p><em>Collector: OB1 Dex collector (<code>Ob1G5CollectionService</code>) — Dexcom G5/G6/G7, especially troublesome phone models</em></p><div class="admonition xdripitem"><p class="admonition-title">Special pairing workaround</p></div><h4 id="manual-slot-number-engineering" tabindex="-1">Manual Slot Number (engineering) <a class="header-anchor" href="#manual-slot-number-engineering" aria-label="Permalink to &quot;Manual Slot Number (engineering)&quot;">​</a></h4><p>Overrides the authentication slot used in the Dexcom auth flow, for engineering/troubleshooting cases.</p><p><em>Collector: OB1 Dex collector (<code>Ob1G5CollectionService</code>) — Dexcom G5/G6/G7</em></p><div class="admonition xdripitem"><p class="admonition-title">Manual Slot Number</p><p> Specify transmitter slot manually, setting this incorrectly will prevent any readings being received.</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',104)])])}const x=a(l,[["render",c]]);export{y as __pageData,x as default};
